  IF v_rec.metadata IS DISTINCT FROM '{"statutory_reference": "Andhra Pradesh Reorganisation Act, 2014 (Act No. 6 of 2014), Section 3", "district_count": 10, "evidence_state": "statutory_act"}'::jsonb THEN
