  END IF;

  -- Assert dataset versions exist
  IF NOT EXISTS (SELECT 1 FROM public.dataset_versions WHERE id = 'ts_lgd_mandals_2026_v1') THEN
    RAISE EXCEPTION 'PRECONDITION_FAILED: dataset_version ts_lgd_mandals_2026_v1 missing';
